\begin{thm}[Simple Transfinite Induction]\ollabel{simpletransrecursion}
Let $\phi(x)$ be a formula such that:
\begin{enumerate}
	\item $\phi(\emptyset)$; and
	\item for any ordinal $\alpha$, if $\phi(\alpha)$ then
	$\phi(\ordsucc{\alpha})$; and 
	\item if $\alpha$ is a limit ordinal and $(\forall \beta \in
	\alpha)\phi(\beta)$, then $\phi(\alpha)$.
\end{enumerate}
Then $\forall \alpha \phi(\alpha)$.
\end{thm}

target:
\begin{thm}[د نامتناهيت هاخوا ساده استقرا]\ollabel{simpletransrecursion}
فرض کړئ $\phi(x)$ داسې فارمول دے چې:
\begin{enumerate}
	\item $\phi(\emptyset)$؛ او
	\item د هر ترتيبي عدد $\alpha$ دپاره، که $\phi(\alpha)$ وي، نو
	$\phi(\ordsucc{\alpha})$ وي؛ او
	\item که $\alpha$ حدي ترتيبي عدد وي او $(\forall \beta \in
	\alpha)\phi(\beta)$ وي، نو $\phi(\alpha)$ وي.
\end{enumerate}
بيا $\forall \alpha \phi(\alpha)$ دے.
\end{thm}

