\begin{thm}[Simple Recursion]\ollabel{simplerecursionschema} 
For any terms $\tau(x)$ and $\theta(x)$ and any set $A$, we can
explicitly define a term $\sigma(x)$ such that:
\begin{align*}
	\sigma(\emptyset) &= A\\
	\sigma(\ordsucc{\alpha}) &= \tau(\sigma(\alpha)) &&
		\text{for any ordinal }\alpha\\
	\sigma(\alpha) &= \theta(\ran{\funrestrictionto{\sigma}{\alpha}})&&
	\text{when }\alpha\text{ is a limit ordinal}
\end{align*}
\end{thm}

target:
\begin{thm}[ساده بازګښت]\ollabel{simplerecursionschema}
د هر دوو ترمونو $\tau(x)$ او $\theta(x)$ او هر سټ $A$ دپاره، يو ترم
$\sigma(x)$ په ښکاره تعريفولے شو چې:
\begin{align*}
	\sigma(\emptyset) &= A\\
	\sigma(\ordsucc{\alpha}) &= \tau(\sigma(\alpha)) &&
		\text{د هر ترتيبي عدد دپاره }\alpha\\
	\sigma(\alpha) &= \theta(\ran{\funrestrictionto{\sigma}{\alpha}})&&
	\text{کله چې }\alpha\text{ حدي ترتيبي عدد وي}
\end{align*}
\end{thm}

