To bring out the foundational importance of the definition of the
$V_\alpha$s, we will present a few basic results about them. We start with a definition:\footnote{There's no standard terminology for ``potent''; this is the name used by \citet{ButtonLT1}.}
\begin{defn}
	The set $A$ is \emph{potent} iff $\forall x((\exists y \in A)x \subseteq y \lif x \in A)$. 
\end{defn}
\begin{lem}\ollabel{Valphabasicprops}
For each ordinal $\alpha$:
\begin{enumerate}
	\item\ollabel{Valphatrans} Each $V_\alpha$ is transitive.
	\item\ollabel{Valphapotent} Each $V_\alpha$ is potent.
	\item\ollabel{Valphacum} If $\gamma \in \alpha$, then $V_\gamma
	\in V_\alpha$ (and hence also $V_\gamma \subseteq V_\alpha$ by
	\olref{Valphatrans})
\end{enumerate}
\end{lem}

target:
د $V_\alpha$ ګانو د تعريف د بنسټيز اهميت د څرګندولو دپاره به ځينې
بنسټيزې نتيجې وړاندې کړو. په يوه تعريف پېل کوو:\footnote{د دې خاصيت
دپاره معياري اصطلاح نشته؛ اصلي متن ئې «potent» بولي، د \citet{ButtonLT1}
د نومولو په تعقيب. دلته ئې پښتو بڼه «توانمن» اخيستل شوې ده.}
\begin{defn}
	سټ $A$ \emph{توانمن} دے، که او يوازې که $\forall x((\exists y \in A)x \subseteq y \lif x \in A)$ وي.
\end{defn}
\begin{lem}\ollabel{Valphabasicprops}
د هر ترتيبي عدد $\alpha$ دپاره:
\begin{enumerate}
	\item\ollabel{Valphatrans} هر $V_\alpha$ متعدي دے.
	\item\ollabel{Valphapotent} هر $V_\alpha$ توانمن دے.
	\item\ollabel{Valphacum} که $\gamma \in \alpha$ وي، نو $V_\gamma
	\in V_\alpha$ دے (او له دې $V_\gamma \subseteq V_\alpha$ هم د
	\olref{Valphatrans} له مخې دے).
\end{enumerate}
\end{lem}

